from app.db import store
import ast

def get_user(user_id: int) -> dict | None:
    return store.get_by_id(user_id)

ALLOWED_OPERATORS = {
    ast.Eq: lambda a, b: a == b,
    ast.NotEq: lambda a, b: a != b,
    ast.Lt: lambda a, b: a < b,
    ast.LtE: lambda a, b: a <= b,
    ast.Gt: lambda a, b: a > b,
    ast.GtE: lambda a, b: a >= b,
}

def _evaluate(node, user):
    if isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Name):
        if node.id in ["id", "name", "email"]:
            return user[node.id]
        raise ValueError(f"Unknown field: {node.id}")
    elif isinstance(node, ast.Compare):
        left = _evaluate(node.left, user)
        for i, op in enumerate(node.ops):
            if type(op) not in ALLOWED_OPERATORS:
                raise ValueError(f"Unknown operator: {type(op)}")
            right = _evaluate(node.comparators[i], user)
            if not ALLOWED_OPERATORS[type(op)](left, right):
                return False
        return True
    elif isinstance(node, ast.BoolOp):
        values = [_evaluate(v, user) for v in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
        raise ValueError(f"Unknown bool operator: {type(node.op)}")
    elif isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.Not):
            return not _evaluate(node.operand, user)
        raise ValueError(f"Unknown unary operator: {type(node.op)}")
    else:
        raise ValueError(f"Unsupported node: {type(node)}")

def filter_users(filter_str: str) -> list[dict] | None:
    try:
        tree = ast.parse(filter_str, mode='eval')
        users = list(store._USERS.values())
        filtered = []
        for user in users:
            if _evaluate(tree.body, user):
                filtered.append(user)
        return sorted(filtered, key=lambda u: u["id"])
    except Exception:
        return None

def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_filter_users(params: dict) -> tuple[int, dict]:
    filter_expr = params.get("where")
    if not isinstance(filter_expr, str):
        return 400, {"error": "invalid filter"}
    result = users.filter_users(filter_expr)
    if result is None:
        return 400, {"error": "invalid filter"}
    return 200, {"users": result}

